	public static VecI VecFrom__I(IterI b, IterI e) {
		VecI v = new VecI();
		int m = (int) (e.i - b.i);
		v.a = new int[m];
		v.n = m;
		for (int i = 0; i < m; i++) v.a[i] = b.a[(int) (b.i + i)];
		return v;
	}

	// ---- VecFromPtr
	@SuppressWarnings("unchecked") public static <T> Vec<T> VecFromPtr(Ptr<T> b, Ptr<T> e) {
		Vec<T> v = new Vec<T>((Fn.F0<T>) null);
		int m = (int) (e.o - b.o);
		v.a = (T[]) new Object[m];
		v.n = m;
		for (int i = 0; i < m; i++) v.a[i] = Elem.Copy(((T) b.a[(int) (b.o + i)]));
		return v;
	}

