	public static <T> Iter<T> begin_VecT(Vec<T> v) { return v.begin(); }
	public static <T> Iter<T> end_VecT(Vec<T> v) { return v.end(); }
	public static <T> long size_VecT(Vec<T> v) { return v.n; }

	// ---- begin_TA/end_TA
	public static <T> Iter<T> begin_TA(T[] a) { return new Iter<T>(a, 0L); }
	public static <T> Iter<T> end_TA(T[] a) { return new Iter<T>(a, (long) a.length); }
	public static IterD begin_TA__D(double[] a) { return new IterD(a, 0L); }
	public static IterD end_TA__D(double[] a) { return new IterD(a, (long) a.length); }
	public static IterZ begin_TA__Z(boolean[] a) { return new IterZ(a, 0L); }
	public static IterZ end_TA__Z(boolean[] a) { return new IterZ(a, (long) a.length); }

