	// ---- lower_bound / upper_bound with a heterogeneous comparator (T the element, V the value)

	public static <T, V> Iter<T> lower_bound_IterT_IterT_V_FuncTVb(Iter<T> b, Iter<T> e, V v, Fn.F2<T, V, Boolean> lt) {
		long first = b.i, len = e.i - b.i;
		while (len > 0) {
			long half = len >> 1, mid = first + half;
			if (lt.apply((T) b.a[(int) mid], v)) { first = mid + 1; len = len - half - 1; } else len = half;
		}
		return Iter.op_Add(b, first - b.i);
	}

	/** lower_bound&lt;T, double&gt;: a reference element, a double value. */
	public static <T> Iter<T> lower_bound_IterT_IterT_V_FuncTVb__OD(Iter<T> b, Iter<T> e, double v, Fn.F2<T, Double, Boolean> lt) {
		long first = b.i, len = e.i - b.i;
		while (len > 0) {
			long half = len >> 1, mid = first + half;
			if (lt.apply((T) b.a[(int) mid], v)) { first = mid + 1; len = len - half - 1; } else len = half;
		}
		return Iter.op_Add(b, first - b.i);
	}

	public static <T, V> Iter<T> upper_bound_IterT_IterT_V_FuncVTb(Iter<T> b, Iter<T> e, V v, Fn.F2<V, T, Boolean> lt) {
		long first = b.i, len = e.i - b.i;
		while (len > 0) {
			long half = len >> 1, mid = first + half;
			if (lt.apply(v, (T) b.a[(int) mid])) len = half; else { first = mid + 1; len = len - half - 1; }
		}
		return Iter.op_Add(b, first - b.i);
	}

	// ---- transform

	/** transform over a string's bytes with a function returning int (::toupper and lambdas around it): each
	 *  result is stored as a char, as the C++ assignment converts it. */
	public static IterB transform_Iteruc_Iteruc_Iteruc_Funcuci(IterB b, IterB e, IterB o, Fn.F1<Byte, Integer> f) {
		for (long i = b.i; i < e.i; i++) o.a[(int) (o.i + (i - b.i))] = (byte) (int) f.apply(b.a[(int) i]);
		return IterB.op_Add(o, e.i - b.i);
	}

	public static IterB transform_Iteruc_Iteruc_Iteruc_Funcucc(IterB b, IterB e, IterB o, Fn.F1<Byte, Byte> f) {
		for (long i = b.i; i < e.i; i++) o.a[(int) (o.i + (i - b.i))] = (byte) f.apply(b.a[(int) i]);
		return IterB.op_Add(o, e.i - b.i);
	}

	public static <T, U> Iter<U> transform_IterT_IterT_IterU_FuncTU(Iter<T> b, Iter<T> e, Iter<U> o, Fn.F1<T, U> f) {
		for (long i = b.i; i < e.i; i++) o.a[(int) (o.i + (i - b.i))] = f.apply((T) b.a[(int) i]);
		return Iter.op_Add(o, e.i - b.i);
	}

	/** transform&lt;byte, byte&gt; (byte-sized elements: sbyte, byte and the enums based on them). */
	public static IterB transform_IterT_IterT_IterU_FuncTU__BB(IterB b, IterB e, IterB o, Fn.F1<Byte, Byte> f) {
		for (long i = b.i; i < e.i; i++) o.a[(int) (o.i + (i - b.i))] = (byte) f.apply(b.a[(int) i]);
		return IterB.op_Add(o, e.i - b.i);
	}

	// ---- <numeric>: accumulate is init = init + x, left to right (the order fixes a floating-point sum)

	public static double accumulate_Iterd_Iterd_d(IterD b, IterD e, double init) { for (long i = b.i; i < e.i; i++) init = init + b.a[(int) i]; return init; }
	public static int accumulate_Iteri_Iteri_i(IterI b, IterI e, int init) { for (long i = b.i; i < e.i; i++) init = init + b.a[(int) i]; return init; }
	public static long accumulate_Iterl_Iterl_l(IterL b, IterL e, long init) { for (long i = b.i; i < e.i; i++) init = init + b.a[(int) i]; return init; }
	public static double accumulate_Iteri_Iteri_d(IterI b, IterI e, double init) { for (long i = b.i; i < e.i; i++) init = init + b.a[(int) i]; return init; }
	/** Over ulongs: the same bits as the signed sum. */
	public static long accumulate_Iterul_Iterul_ul(IterL b, IterL e, long init) { for (long i = b.i; i < e.i; i++) init = init + b.a[(int) i]; return init; }
	public static <T, A> A accumulate_IterT_IterT_A_FuncATA(Iter<T> b, Iter<T> e, A init, Fn.F2<A, T, A> op) { for (long i = b.i; i < e.i; i++) init = op.apply(init, (T) b.a[(int) i]); return init; }

	public static void iota_Iteri_Iteri_i(IterI b, IterI e, int v) { for (long i = b.i; i < e.i; i++) b.a[(int) i] = v++; }
	public static void iota_Iterul_Iterul_ul(IterL b, IterL e, long v) { for (long i = b.i; i < e.i; i++) b.a[(int) i] = v++; }

	// ---- equality of doubles and floats as C#'s double.Equals: 0.0 equals -0.0, NaN equals NaN

	static boolean eqD(double x, double y) { return x == y || (x != x && y != y); }
	static boolean eqF(float x, float y) { return x == y || (x != x && y != y); }
